  transformer:{chapter:'power',name:'Transformer',description:'Uses magnetic coupling to change alternating-current voltage. Here, incoming utility power steps down before distribution through the facility.',path:'Utility → transformer → switchgear',insight:'Voltage is changed in stages. The exact levels depend on the electrical design.',source:doe},
  switchgear:{chapter:'power',name:'Switchgear',description:'Switches and circuit breakers route electricity, isolate equipment, and interrupt fault currents.',path:'Transformer → switchgear → UPS / distribution',insight:'Isolation lets a section be disconnected for a fault or planned work. Alternate routes must be designed to carry the remaining load.',source:doe},
  ups:{chapter:'power',name:'UPS & batteries',description:'An uninterruptible power supply uses stored energy to keep its connected equipment running during a supply interruption.',path:'Normal supply or backup → UPS → IT distribution',insight:'Ride-through is finite and depends on stored energy and load. It can cover the gap while standby generation starts.',source:doe},
  generator:{chapter:'power',name:'Standby generator',description:'An engine drives an electrical generator. Transfer equipment can connect this alternate supply when the normal source is unavailable.',path:'Generator → transfer equipment → backup bus → loads',insight:'This is a parallel supply branch, not a stage electricity must always pass through. Fuel and maintenance constrain sustained operation.',source:doe},
  pdu:{chapter:'power',name:'Power distribution',description:'Distribution panels, busways, and rack power strips carry electricity from the facility supply to the individual server power supplies.',path:'UPS → distribution → rack PDU → server power supply',insight:'A server power supply converts incoming power into the regulated DC voltages its electronics need.',source:doe},
