  cpu:{chapter:'compute',name:'CPU',description:'The central processor runs instructions and coordinates the operating system and applications. It accesses active data through the memory system.',path:'Instructions + data → CPU → results',insight:'Clock speed alone does not determine useful work. Memory access, software, and the workload all influence performance.',source:ibm},
  gpu:{chapter:'compute',name:'GPU / accelerator',description:'Many parallel execution units work on suitable computations at once, such as matrix operations used by AI models.',path:'Data → parallel computation → results',insight:'A GPU accelerates workloads that suit it. It still needs data, memory, power, cooling, and supporting software.'},
  memory:{chapter:'compute',name:'Working memory',description:'RAM holds instructions and data being used by the processors. Ordinary DRAM loses its contents when power is removed.',path:'Storage → RAM ↔ processor',insight:'Capacity determines how much working data fits nearby. Bandwidth determines how fast it can be delivered.'},
